#include "stdafx.h"#include "Server.h"#include <rsuMemoryManager.h>#ifdef _MANAGED#pragma managed(push, off)#endifHINSTANCE g_hInst = 0;KRsuMemoryManager g_SOEmemory;BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    g_hInst = hModule;    g_SOEmemory.Create( "SOE_Mem", 3 );    break;  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifextern "C" Q_DECL_EXPORT         IRsuModel* CreateServer(LPCSTR ObjName ){  IRsuModel *pModel = new KServer( ObjName );  return pModel;}